begin;create extension if not exists pgtap with schema extensions;select extensions.plan(9);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)values('13200000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','twitter-232@example.com','',now(),now(),now());
insert into public.organizations(id,name,slug,created_by)values('23200000-0000-4000-8000-000000000001','Twitter 232','twitter-232','13200000-0000-4000-8000-000000000001');insert into public.organization_members(organization_id,user_id,role,invited_by)values('23200000-0000-4000-8000-000000000001','13200000-0000-4000-8000-000000000001','admin','13200000-0000-4000-8000-000000000001');
create temporary table t232(identity_id uuid,connection_id uuid,profile_id uuid,epoch_id uuid,program_id uuid,reservation_id uuid)on commit drop;grant select,insert,update on t232 to service_role;insert into t232 default values;set local role service_role;select set_config('request.jwt.claim.role','service_role',true);
do $$declare identity jsonb;connection jsonb;profile jsonb;reservation jsonb;pid uuid:=gen_random_uuid();begin identity:=public.twitter_register_identity_and_grant('23200000-0000-4000-8000-000000000001','zernio-232');connection:=public.twitter_upsert_connection_credentials('23200000-0000-4000-8000-000000000001',(identity->>'identityId')::uuid,'C','zp-232',repeat('encrypted',5),repeat('e',64),'api','scope','13200000-0000-4000-8000-000000000001','twitter-232@example.com');profile:=public.twitter_sync_profile_from_zernio('23200000-0000-4000-8000-000000000001',(connection->>'connectionId')::uuid,'za-232','xu-232','perfil232','Perfil',null,true,false,true,false,'free','[]');insert into public.twitter_programs(id,organization_id,schedule_kind,starts_at,ends_at,interval_minutes,total_requested,funded_count,unfunded_count,reserved_micros,rate_card_id,rate_card_version,review_digest,idempotency_key,created_by)select pid,'23200000-0000-4000-8000-000000000001','interval',now()-interval '5 minutes',now(),1,3,3,0,45000,id,version,repeat('c',64),'program-232','13200000-0000-4000-8000-000000000001'from public.twitter_rate_cards where active;reservation:=public.twitter_create_wallet_reservation('23200000-0000-4000-8000-000000000001',(identity->>'identityId')::uuid,(connection->>'connectionId')::uuid,1,'post_dm_create','publication',pid,45000,1,'reservation-232');insert into public.twitter_program_reservations values(pid,(reservation->>'reservationId')::uuid,(identity->>'identityId')::uuid,'post_dm_create');update t232 set identity_id=(identity->>'identityId')::uuid,connection_id=(connection->>'connectionId')::uuid,profile_id=(profile->>'profileId')::uuid,epoch_id=(profile->>'epochId')::uuid,program_id=pid,reservation_id=(reservation->>'reservationId')::uuid;end$$;
insert into public.twitter_publication_items(organization_id,program_id,profile_id,connection_epoch_id,connection_id,identity_id,slot_index,execute_at,content,weighted_characters,category,amount_micros,idempotency_key)select '23200000-0000-4000-8000-000000000001',program_id,profile_id,epoch_id,connection_id,identity_id,x,now()-interval '2 minutes','lease '||x,8,'post_dm_create',15000,'item-232-'||x from t232 cross join generate_series(0,2)x;
select public.twitter_cancel_publication_scope('23200000-0000-4000-8000-000000000001',(select id from public.twitter_publication_items where slot_index=2),null,null,null,'cancelar apenas item','cancel-item-232');
select extensions.is((select count(*)::bigint from public.twitter_publication_items where status='cancelled'),1::bigint,'cancelamento por item não amplia escopo');select extensions.is((select reserved_micros from public.twitter_wallets where identity_id=(select identity_id from t232)),30000::bigint,'cancelamento libera somente um hold');
create temporary table c232a as select * from public.twitter_claim_publication_items('lease-232',1);grant select on c232a to service_role;update public.twitter_publication_items set claimed_at=now()-interval '10 minutes' where id=(select item_id from c232a);select public.twitter_recover_expired_claims(60);
select extensions.is((select status::text from public.twitter_publication_items where id=(select item_id from c232a)),'retry','lease antes da chamada volta para retry');select extensions.is((select status::text from public.twitter_item_holds where item_id=(select item_id from c232a)),'reserved','lease pré-chamada preserva reserva');
update public.twitter_publication_items set next_attempt_at=now()-interval '1 minute' where id=(select item_id from c232a);create temporary table c232b as select * from public.twitter_claim_publication_items('lease-232',1);grant select on c232b to service_role;select public.twitter_start_external_attempt((select attempt_id from c232b),'start-lease-232');update public.twitter_publication_items set claimed_at=now()-interval '10 minutes' where id=(select item_id from c232b);select public.twitter_recover_expired_claims(60);
select extensions.is((select status::text from public.twitter_publication_items where id=(select item_id from c232b)),'outcome_unknown','lease pós-chamada vira incerto');select extensions.is((select status::text from public.twitter_item_holds where item_id=(select item_id from c232b)),'outcome_unknown','resultado incerto mantém hold');select extensions.is((select reserved_micros from public.twitter_wallets where identity_id=(select identity_id from t232)),30000::bigint,'recuperação não cria nem devolve saldo');
select extensions.ok(not has_function_privilege('authenticated','public.twitter_cancel_publication_scope(uuid,uuid,uuid,uuid,uuid[],text,text)','EXECUTE'),'cliente não chama RPC crítica');select extensions.is((select count(*)::bigint from pg_constraint c join pg_class t on t.oid=c.conrelid join pg_class f on f.oid=c.confrelid where t.relname like 'twitter_%'and f.relname in('instagram_profiles','publication_items')),0::bigint,'sem FK Instagram');
select jsonb_build_object('finish',(select jsonb_agg(v)from extensions.finish()v),'reserved',(select reserved_micros from public.twitter_wallets where identity_id=(select identity_id from t232)))diagnostics;rollback;
